def can_partition(n, a):
    if n == 2:
        if a[0] >= a[1]:
            return 1
        return 0
    if n == 1:
        return 0
    if a[0] < a[1]:
        return can_partition(n-1, a[1:])
    if a[1] < a[0]:
        return can_partition(n-1, a[:1] + a[2:])
    return can_partition(n-1, a)

def game_winner(T, N, A):
    for _ in range(T):
        if N <= 60:
            if can_partition(N, A[:]):
                return "Alice"
            else:
                return "Bob"
        else:
            if N % 2 == 0:
                if can_partition(N//2, A[:]):
                    return "Alice"
                else:
                    return "Bob"
            else:
                if can_partition((N+1)//2, A[:]):
                    return "Alice"
                else:
                    return "Bob"

# Example usage
