from typing import List

def count_safe_plans(n: int, m: int, storehouse: List[str]) -> int:
    from functools import lru_cache

    mod = 10**9 + 7

    @lru_cache(None)
    def dp(i: int, j: int, has_guard: int, is_empty: bool) -> int:
        if i == n:
            return has_guard == 0 and is_empty
        if j == m:
            return 0

        take = 0
        if storehouse[i][j] == 'x':
            take = dp(i + 1, j, has_guard + 1, False)

        drop = 0
        for k in range(j, min(m, j + 1 + (i + 1) // 2)):
            if k != j:
                for l in range(k + 1, min(m, j + 1 + (i + 1) // 2)):
                    if j + 1 + l >= m:
                        break
                    drop += dp(i + 1, l, has_guard + 1, True)
                    drop %= mod

            if k != j:
                take += drop
                take %= mod

        take %= mod
        drop %= mod
        return (take + drop) % mod

    return dp(0, 0, 0, False)

if __name__ == "__main__":
    n, m = map(int, input().split())
    storehouse = [input() for _ in range(n)]
    print(count_safe_plans(n, m, storehouse))
