    for i in range(m):
        B_buckets[B[i]].append(i+1)

    total = 0
    for i in range(n // 2 + 1):
        for b in B_buckets:
            total += a[n // 2 + 1 - i] * min(len(B_buckets[b]), i)
            for j in range(1, len(B_buckets[b]) - i + 1):
                total += a[n // 2 + 1 - i - j] * max(0, -1 * i * (2*j - 2) + min(2*j - 1, i))

