    max_val_pairs = deque()
    val_pair = deque()

    for length in range(1, N + 1):
        val_pair.append((length, 0))
        max_val_pairs.append([-1, 0])

    min_days = [0] * (N + 1)

    for i in range(1, len(max_val_pairs)):
        left, val = val_pair[i - 1]
        left += 1
        min_days[i] = min(min_days[i], max_val_pairs[i][1])
        while max_val_pairs[i][1] < val:
            left -= 1
            val -= 1
            while i > 0 and max_val_pairs[i][0] > left:
                i -= 1
            if i > 0:
                pair = max_val_pairs[i]
                current_max = pair[1]
                next_val_pair = deque([(i_x + 1, i_y + 1) for i_x, i_y in [(1, pair[0] + 1), (pair[0], pair[1] + 1)]] if pair[0] > left + 1 else [])
                max_val_pairs[i] = pair[0], pair[1] + 1
