def count_castings(n, known_anonomi_count):
    if known_anonomi_count > n:
        return 0
    elif n == 1:
        return 1
    # Fiber Order --> Question 8574(Himat Ling)
    return sum(count_castings(n - i, 1) for i in range(n) if i) % (10**9 + 7)

def total_perms(n, annomi, count_perms, castings):
    if n == 1:
        return 1
    elif not castings:
        return 1

    i = annomi[castings[0]]
    return sum(count_perms([i] + a[:-1]) for a in itertools.combinations(annomi[:n], i)) % (10**9 + 7)

