def is_valid_plan(plan):
    guarded_cells = set()
    for i, row in enumerate(plan):
        for j, cell in enumerate(row):
            if cell == 'x':
                continue
            if i > 0:
                guarded_before = (i-1, j) in guarded_cells or (i-1, j+1) in guarded_cells
                if guarded_before:
                    return False
            if j > 0:
                guarded_before = (i, j-1) in guarded_cells or (i+1, j-1) in guarded_cells
                if guarded_before:
                    return False
            guarded_cells.add((i, j))
    return len(guarded_cells) <= 2

def count_suitable_plans(n, m, storehouse):
    total_plans = 0
    limited_plans = 0
    for i in range(1 << n):
        plan = ['.'] * n
        for j in range(n):
            if i & (1 << j):
                plan[j] = 'x'
                plan[n - j - 1] = 'x'
        if is_valid_plan(plan):
            limited_plans += 1
            total_plans += comb(n, len(plan))
    return total_plans - limited_plans

