def paint_tree(n, edges):
    adjacency_list = [defaultdict(int) for _ in range(n + 1)]
    for u, v in edges:
        adjacency_list[u][v] = 1
        adjacency_list[v][u] = 1

    def bfs(node, colors, parent):
        queue = [(node, COLORS[0])]
        parent[node] = colors[0]
        cost = [0]
        while queue:
            v, color = queue.pop(0)
            for neighbor in adjacency_list[v]:
                if neighbor != parent[v]:
                    flg = not (node == v and len(colors) > 1)
                    if adjacency_list[v][neighbor] == 1 and (flg or (colors[neighbor] != colors[v] and two_same_neighbors(colors, neighbor))):
                        return -1
                    colors[neighbor] = color
                    parent[neighbor] = color
                    queue.append((neighbor, color))
                    cost.append(cost[-1]+1)
        return max(cost)

    COLORS = list(range(10**6)) + [-1]
    parent = [-1] * (n + 1)
    next = [1]
    two_same_neighbors = lambda colors, vertex: len(set(colors[neighbor] for neighbor in adjacency_list[vertex]) == 2]
    while next[-1] != 2:
        child = bfs(next[-1], COLORS[:2], parent[next[-1]]) or bfs(next[-1], COLORS[2:5], parent[next[-1]]) or bfs(next[-1], COLORS[5:], parent.next[-1]) or bfs(next[-1], COLORS[8:], parent[next[-1]])
        if child == -1:
            return
        if child > 2:
            COLORS[node] = COST[child]
        else:
            COLORS = [COST[child]]*2 + COLORS
        next.pop()
        next.append(max(COLORS))
    return next[-1]

