from collections import defaultdict

def min_tree_painting_cost(n: int) -> tuple:
    tree = defaultdict(list)
    edge_count = 0
    edge_colors = [0] * n

    for _ in range(n):
        level = int(input().strip())
        edge_count += 1
        parents = input().strip().split()
        for parent in parents:
            parent = int(parent)
            tree[parent].append(edge_count)
            edge_count += 1

    for parent, children in tree.items():
        if len(children) < 3:
            edge_colors[parent] = children[0]

    edge_colors_used = [set() for _ in range(n)]

    def rec(node, parent_color):
        for child in tree[node]:
            if edge_colors_used[node].intersection(edge_colors[child]):
                return rec(child, *edge_colors[child])

        colors = set()
        for child in tree[node]:
            colors.update(edge_colors_used[child])

        used = edge_colors_used[node]
        edge_colors_used[node] |= colors
        used.add(edge_colors[node])

        return (1 + max(colors | set([node])) - max(used, {max(used | {node})}), 1)

    _, max_cost = rec(1, set())
    return tuple(max_cost)

print(' '.join(map(str, min_tree_painting_cost(int(input())))))
