from collections import defaultdict

def solveQueries(n, b, query_count, queries):
    permutation = [0] * n
    # Create a graph using the constraints provided by the initial 'b' array
    graph = defaultdict(list)
    for i in range(n):
        for j in range(i):
            if b[j] == i - j:
                graph[j].append(i)
                graph[i].append(j)

    visited = [False] * n

    # Perform DFS to find cycles in the graph
    def dfs(node):
        visited[node] = True
        for child in graph[node]:
            if not visited[child]:
                dfs(child)

    for node in range(n):
        if not visited[node]:
            dfs(node)

    # Two phase algorithm
    start_nodes = []
    for node in range(n):
        if visited[node]:
            start_nodes.append(node)

    # Construct the two phase permutation
    phase1_perm = [start_nodes[0]]
    while start_nodes and phase1_perm[-1] < len(start_nodes) - len(phase1_perm):
        phase1_perm.append(start_nodes[phase1_perm[-1]])
        del start_nodes[phase1_perm[-1]]
    phase2_perm = [start_nodes[-1]]
    while phase1_perm and start_nodes and phase1_perm[-1] >= len(start_nodes) - len(phase2_perm):
        phase2_perm.append(start_nodes[phase1_perm[-1]])
        del start_nodes[phase1_perm[-1]]
    phase2_perm += start_nodes

    # Confirm the permuation is sound by checking the number of inversions
    for i in range(n):
        if b[i] != b[phase2_perm.index(phase1_perm[i])]:
            return "IMPOSSIBLE"

    # ANSWER RETURN
    ans = []
    for query in queries:
        if query[0] == 1:
            if query[1] in graph[query[2]] and query[1] < n and b[query[1]] >= query[2]:
                ans.append(query[1] + 1)
            else:
                return "IMPOSSIBLE"
        elif query[0] == 2:
            ans.append(phase1_perm.index(query[1]))
        else:
            return "IMPOSSIBLE"
    return " ".join(map(str, ans))

