import math

def calculate_path_length(g, r, n, red_1, red_2):
    total_green_time = (n // g + 1) * g
    if red_1 < g and red_2 < g:
        red_shift = 2 * min(g, red_2 - red_1)
    elif red_1 < g and red_2 >= g:
        red_shift = min(g, red_1 + 2 * (n // g + 1) - red_2)
    elif red_1 >= g and red_2 < g:
        red_shift = g - (n // g)
    elif red_1 >= g and red_2 >= g:
        red_shift = 0

    total_red_time = n // g * g + (n % g)

    return total_green_time + red_shift + red_time

