from heapq import heappush, heappop, heapify

def min_trains(n, t, k, data):
    timeline = {i: {'people': 0, 'capacity': k, 'arrival': t, 'overfill': 0} for i in range(n)}

    for si, sb, sc in data:
        timeline[si]['people'] += (sc - sb)

    trains = []
    for i in range(n):
        if timeline[i]['overfill'] > 0:
            heappush(trains, (timeline[i]['overfill'], i))

        timeline[i]['people'] += timeline[i]['overfill'] 

        if timeline[i]['people'] > timeline[i]['capacity'] or timeline[i]['overfill'] < timeline[i]['people'] - timeline[i]['capacity']:
            timeline[i]['overfill'] = timeline[i]['capacity'] - timeline[i]['people']
        else:
            timeline[i]['overfill'] = 0

    covered = 0
    while trains:
        overfill, i = heappop(trains)
        if timeline[i]['people'] <= timeline[i]['capacity']:
            covered += 1

        if timeline[i]['people'] != 0:
            timeline[i]['overfill'] = timeline[i]['capacity'] - timeline[i]['people']

    hour = sorted(timeline.items(), key=lambda x: x[0] % t)[0][0]
    while hour % t == 0:
        covered += 1
        hour += 1

    return covered

