    root = 1
    graph = {root: deque()}
    last_new_vertex = 1
    magic_colors = set(range(1, n + 1))

    for i in range(1, n + 1):
        if last_new_vertex == root:
            magic_colors.remove(last_new_vertex)

        parent = graph[root].popleft()
        new_color = len(magic_colors)
        graph[parent].appendleft(root)
        graph[root] = deque([parent])

        dummy = True
        while last_new_vertex not in colors:
            if root == i:
                colors.add(new_color)
            if dummy and i < n and i < last_new_vertex:
                dummy = False
                graph[parent].appendleft(new_color)
            last_new_vertex += 1
            if len(graph[parent]) == 2:
                colors.add(new_color)

