import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def number_of_colors(n, previous_view):
    total_colors = 1 + sum(is_prime(i) for i in range(previous_view + 1, n + 1))
    edges = [(n, i) for i in range(n)]
    for i in range(n):
        assigned_number = i + 1
        for j in edges:
            if j[0] not in previous_view:
                j[1] = assigned_number
                assigned_number += 1
    while sum(is_prime(i) for i in range(previous_view + 1, n)) < len(previous_view) + 1:
        previous_view = sorted(list(previous_view))
        previous_view = [-previous_view[0]]
        for i in range(1, len(previous_view)):
            previous_view.append(previous_view[i] + previous_view[i-1])
        total_colors += 1
    return total_colors

def minimum_cost(n, previous_view, edges):
    if not len(previous_view) + 1 < n:
        return "Invalid input"
    divisible_by = len(previous_view) - 1
    if len(previous_view) == not (n + previous_view[-1]):
        return len(previous_view)
    divisible_by -= 1
    if len(previous_view) == 0:
        return len(previous_view)
    edges = sorted(list(edges))
    arr = [i + 1 for i in range(n)]
    for i in range(len(edges)):
        if edges[i][1] == divisible_by:
            edges[i] = (edges[i][0], len(arr))
            arr.append(len(arr))
        else:
            arr = [edges[i] for i in range(len(edges))]
            del arr[edges[i][1]]
    return divisible_by + 1 + float("inf") * (len(edges) - 1)
