def a_sum_check(a, n):
    total = 0
    stack = []
    for i, num in enumerate(a):
        while stack and num > stack[-1]:
            total += stack.pop()
        if num not in stack:
            left = n - max(stack) if stack else n
            if left > i:
                stack.append(num)
        if num not in stack:
            if stack:
                left = n - stack[0]
                total -= left
            else:
                left = n
                stack.append(num)

    return total

