import collections

def build_graph(n, queries):
    parent = {i: i for i in range(n)}
    edges = collections.defaultdict(set)

    for operation, start, end, label in queries:
        if operation == '+':
            edges[start].add((end, label))
            parent[start] = end
        elif operation == '-':
            if (start, end) in edges:
                edges[start].remove((end, label))
                if len(edges[start]) == 0:
                    parent[start] = start

    return parent, edges

def find_cycle(parent, edges, start):
    visited = set()
    visited.add(start)

    stack = [(start, [start])]
    while stack:
        node, path = stack.pop()
        for neighbor, _ in edges[node]:
            if neighbor in visited:
                reverse_path = list(reversed(path))
                reverse_path.remove(node)
                reverse_path.extend([neighbor])
                if path != reverse_path:
                    return path
            elif neighbor not in visited:
                visited.add(neighbor)
                stack.append((neighbor, path + [neighbor]))

    return []

def solve_queries(parent, edges, queries):
    results = []
    for query in queries:
        if query.startswith('?'):
            k = int(query[2:])
            results.append(f"YES" if len(find_cycle(parent, edges, None)) <= k else "NO")
        else:
            start, end, _, label = query.split()
            parent[start] = end
    return results

