import sys

def palindrome_degree(n, a):
    a = [a[i] for i in range(n)]
    left_right_count, temp, odd_found = 0, {}, 0
    for i in range(n):
        if a[i] != a[n - i] and a[i] in temp:
            left_right_count += (temp[a[i]] * 2 + 1)
        elif a[i] not in temp and not odd_found:
            temp[a[i]] = 1
            odd_found = 1
        elif a[i] not in temp:
            temp[a[i]] = temp.get(a[i], 0) + 1
        elif a[i] in temp:
            temp[a[i]] += 1
        a[i], a[n - i] = a[n - i], a[i]
    temp.clear()
    odd_found = 0
    left_right_count += n
    temp = {}
    for b in a:
        if b in temp:
            temp[b] += 1
        else:
            temp[b] = 1
    for k, v in temp.items():
        if (v - n // 2) % 2 == 0:
            left_right_count += 1
    if odd_found and abs(n % 2 - left_right_count) == 1:
        left_right_count += 1
    return left_right_count

