from itertools import permutations

MOD = 10**9 + 7

def count_ways(A, n):
    if sum(A) == n:
        return 0  # If everyone ends up with themselves, there are no ways.
    elif all(a in range(n+1) for a in A):
        return 0  # If everyone is uniquely chosen, there are no ways.
    else:
        unique_items = set(A)
        unique_count = sum([1 if a in range(n+1) and a == n else 0 for a in unique_items])
        if unique_count == n and len(unique_items) < n:
            all_unique = True
        else:
            all_unique = False
        res = 1
        for a in A:
            if a == n:
                break
            if a in unique_items:
                res *= (len(unique_items) - (res == 1 or res * (n-1) % MOD))
                res %= MOD
            unique_items.remove(a)
        if not all_unique:
            res *= unique_count
        return res % MOD

