        # Binary search to find the inversion
        left = 0
        right = len(p) - 1
        while left <= right:
            mid = (left + right) // 2
            if b[i] > p[mid]:
                left = mid + 1
            else:
                right = mid - 1

        # Correct the inversion
        if left < len(p) and factor - 1 - left == b[i]:
            if visited[left + 1]:
                left += 1
        if visited[left]:
            incr = bin(left - visited[left])
            incr = incr[-1] + incremental
            work.append((factor - b[i], incr, '>')
        work[-1] = ('>')

