import sys

def max_efficiency(n: int, m: int, commercials: List[Tuple[int, int]], channels: List[Tuple[int, int, int]]) -> int:
    commercials.sort()
    channels.sort()

    dp = [0] * ((len(commercials) + 1) * 2)
    for i in range(len(channels)):
        left = 0
        for j in range(len(commercials)):
            left = max(left, j * channels[i][2] - 2 * dfs_get_x(dp, j))

        left_func = left if j >= 0 else sys.maxsize
        dp[(2 * channels[i][1] - channels[i][2] + left) % (2 * left_func) + 1] = dp[(channels[i][1] - channels[i][2] + left) % left_func + 1] + channels[i][2]

    return dp[-1]

def dfs_get_x(dp: List[int], n: int) -> int:
    left = 0
    for i in range(n - 1, -1, -1):
        if not (i - n <= dp[i] <= i - n + 1):
            left = i
        else:
            if i - 1 > dp[i]:
                dp[i - 1] = i
                break
            else:
                for left in range(i - 1, i - n, -1):
                    if i - 1 - left + 1 + right_filled(dp, i - 2) < i + 1 - left - left_filled(dp, i):
                        dp[left] = i
                        break
    return left if n == len(dp) - 1 else left_filled(dp, n - 1)

def left_filled(dp: List[int], n: int) -> int:
    tmp = dp[n]
    for i in range(n, -1, -1):
        if dp[i] - tmp - 1 < n:
            dp[i] -= tmp
            continue
        break
    return tmp

def right_filled(dp: List[int], n: int) -> int:
    tmp = dp[n]
    for i in range(n + 1, len(dp)):
        if dp[i] - tmp - 1 > n:
            dp[i] -= tmp
            continue
        break
    return tmp

