def grid_turle(grid):
    n, m = len(grid), len(grid[0])
    up = [0] * m + [2 for _ in range(m - 1)]
    down = [0] * (m + 1) + [1 for _ in range(n - 1)]
    left = [-1] * m + [2 for _ in range(m - 1)]
    right = [1] * (m + 1) + [0 for _ in range(n - 1)]

    def backtrack(position, count, used):
        if used >= 2:
            return 0
        if position[1] >= n:
            return 0
        if grid[position[0]][position[1]] == 'x':
            old_count = count
            count += 1
            # move right
            new_count = count
            for i in range(position[1] + 1, m):
                if grid[position[0]][i] == 'x':
                    count = old_count
                    break
                count += 1
            # move down
            for i in range(position[0] + 1, n):
                if grid[i][position[1]] == 'x':
                    count = old_count
                    break
                new_count = count
                count += 1

            if count > 1:  # If we use 2 or more coordinates in current subtree
                depth_turles = count
                return (PrefixSums(m + 1, m + 1)[m + n - position[0] - 1][m+position[1]] -
                        PrefixSums(m + 1, m + 1)[m + n - position[0]][m+position[1]] +
                        depth_turles) % MOD
            else:  # If use one coordinate, subtract that point
                depth_turles = count
                depth_turles = DepthSum(m + 1, m + 1)[position[0]][position[1]] - add(one_diff(m + 1, m + 1, position[1], n, m))[position[0]]
                return (PrefixSums(m + 1, m + 1)[m + n - position[0] - 1][position[1]] -
                        PrefixSums(m + 1, m + 1)[position[0]][position[1]]) % MOD 
