from itertools import permutations

# Function to calculate factorials
def factorial(n):
    return 1 if n == 0 else n * factorial(n - 1)

# Function to calculate modular inverses
def mod_inverse(x, p):
    return pow(x, p - 2, p)

# Function to calculate combinations (n choose k) modulo p
def comb_mod_n_choose_k(n, k, p):
    return (factorial(n) * mod_inverse(factorial(k), p) * mod_inverse(factorial(n - k), p)) % p

# Function to calculate the number of ways to assign mannequins in a game with pmult condition
def ways_to_assign_mannequins(n, A, p=10**9 + 7):
    MODP = (p * MODP) // MOD
    has_mannequin = 1
    not_decided = list(range(1, n + 1))
    result = 1

    for i, A_i in enumerate(A):
        if A_i == 0:
            if has_mannequin:
                not_decided.remove(i)
                continue
        else:
            if A_i > 1 or not has_mannequin:
                return 0  # Impossible

        if has_mannequin:
            j = next(j for j in range(n) if j != A_i)
        else:
            j, one = divmod(i, n)
            if one:
                j = j + 1 if not i else j # Use default populated one-mannequin
            else:
                j = (n - i) - 1 if not i else j

        if A_i < i:
            k = next(k for k in range(n) if k != i)  # Was not decided

        else:
            k, one = divmod(i, j)
            if one:
                k = k + 1 if not i else k  # Was not decided
            else:
                k = j + k - i + 1 if not i else k
                #k = i - j if not i else k

        # factorial count
        num_ways = 1
        found = False
        used = {}
        if k - 1 >= n:
            temp = 0
        else:
            temp = k - 1 if k - 1 == i else k - 2
        for j_id, j in enumerate(range(1, j + 1)):
            if j in used and j not in not_decided:
                continue
            temp = i - j + 2
            while len(not_decided) > 0 and temp <= n + n:
                if k >= temp % j:
                    if temp % j * (j - 1) // 2 == i - temp:
                        if i - temp == 0 or temp in not_decided:
                            result = (result * comb_mod_n_choose_k(n, temp) * mod_inverse(comb_mod_n_choose_k(n - 1, temp - i + 1), p)) % p
                            find_indices = [found, j_id] 
                            used.pop(j)
                            if j in not_decided: not_decided.remove(j)
                            found = True
                        else:

                            result = 0
                            break
                    elif temp not in not_decided:
                        not_decided.remove(temp)
                else:
                    result = 0
                    break
                temp += 1
            else:
                result = 0
                break
            used[temp] = True
            num_ways = (num_ways * n) % p

        found = False

        if result == 0 or num_ways == 0:
            return 0

        if result != 0 and num_ways != 0:            
            result *= num_ways % MODP
            result %= MODP
        has_mannequin = 0    

    return int(result)

