from collections import defaultdict, deque

# Create a graph from a list of edges
def create_graph(edges):
    graph = defaultdict(list)
    for u, v, char in edges:
        graph[u].append((v, char))
    return graph

# Find edges that are involved in a palindrome cycle
def find_palindrome_edges(graph, s, k):
    if len(s) < k:
        return []
    rev_s = s[::-1]
    for i, j in graph[s[0]]:
        if j == rev_s[i]:
            res = []
            for u, ch in graph[j]:
                if u != i and u != j and (i in graph[u][0] or i in graph[u][1]) and graph[u][0][1] == graph[u][1][0]:  # Edge e in cycle and reverse e in reverse cycle
                    res.append((u, ch))
            if len(res) >= k and (k > len(res) or set(res) <= set(find_palindrome_edges(graph, u, k - len(res)))):
                return res
    return []

# Main query function
def query(graph, k):
    if k == 2:
        if graph.get("1", []):
            s = "1" + list(graph["1"].keys())[0]
            return "YES" if set(graph[s[0]][0]) == set(graph[s[-1]][0]) else "NO"
        return "NO"
    candidates = [e[0] for e in [v for v in graph[i] for i in v] for i in v]
    for e, ch in graph[i]:
        if e != i and e in candidates and find_palindrome_edges(graph, i, k) or e in graph[i][0]:
            return "YES"
    return "NO"

# Main function to process multiple queries
def solve():
    n, m = map(int, input().split())
    edges = []
    for _ in range(m):
        op, *args = input().split()
        u, v, c = int(args[0]), int(args[1]), args[2].lower() if len(args) > 2 else None
        if op == '+':
            edges.append((u, v, c))
        elif op == '-':
            if (u, v) in edges and edges[edges.index((u, v))][2] != c:
                del edges[edges.index((u, v))]
        elif op == '?':
            edges.append((u, v, c))
    s = "n" + "".join(str(i) for i in range(1, n + 1))
    print("YES" if find_palindrome_edges(create_graph(edges), s, len(s)) else "NO")

