def cross_bridge(n, m, safety_islands, g, r):
    if n < 2 or m < 2:  # Impossible to cross without green light
        return -1

    islands_set = set(safety_islands)
    moves = {0: 0}
    for d in range(1, n + 1):
        if d in islands_set:
            moves[d] = 1 + moves[0]
        elif d == 0:
            moves[d] = g + moves[n]
        else:
            moves[d] = max(moves[d - 1], 1 + moves[max(0, d - g - 1)])

    return moves[n] if moves[n] <= n + r else -1

