from collections import defaultdict

def calculate_happiness(s1, s2):
    one_count = s1.count('1')
    zero_count = s1.count('0')
    if one_count > zero_count:
        return one_count + calculate_happiness(s2, '') if s2 else 0
    return calculate_happiness('', s2)

def max_happiness(s):
    return max(calculate_happiness('', sub) for sub in split(s))

def split(s):
    i = 0
    while i < len(s):
        if s[i] == '1':
            left = ''
            while i + 1 < len(s) and s[i + 1] == '1':
                left += '1'
                i += 1
            right = ''
            while i + 1 < len(s) and s[i + 1] == '0':
                right += '0'
                i += 1
            if right and i + 1 < len(s):
                num_zeros = len(right)
                if i + 1 + len(right) < len(s):
                    if s[i + 1 + len(right)] == '1':
                        num_zeros += 1
                if left and num_zeros > len(left):
                    new_sub_s = left + ('0' * len(right))
                    yield new_sub_s
                else:
                    new_sub_s = left
                    yield new_sub_s + right*(num_zeros // len(right))
                yield from split(new_sub_s)
                return
        i += 1
    yield s

def process_queries(n, q, queries):
