        check_queue = [(start_gangster, 0)]

        while check_queue:
            gangster, cmd = check_queue.pop()
            if cmd == 1 and len(known_friends) < X:
                known_friends.add(gangster)
                for next_gangster in range(N):
                    if graph[next_gangster].append(gangster):
                        check_queue.append((next_gangster, -cmd))
            elif cmd == -1 and len(known_friends) < X:
                known_friends = {friend for friend in known_friends if friend % (friend - gangster) == 0}
                check_queue = []
                check_queue.append((gangster, 0))

        return len(known_friends) >= X

    # Try to find a subset of gangsters where everyone in it will know about everyone else
    for gangsters_to_interrogate in range(N, -1, -1):
        if can_find_friends(gangsters_to_interrogate):
            min_gangs = gangsters_to_interrogate
            break

    return min_gangs
